#include <bits/stdc++.h>
using namespace std;
long long largestRectHistogram(vector<int>& h){
    stack<int> st; long long best=0; int n=h.size();
    for (int i=0;i<=n;i++){
        int cur = (i==n)?0:h[i];
        while(!st.empty() && h[st.top()]>=cur){
            int height = h[st.top()]; st.pop();
            int width = st.empty()? i : i-st.top()-1;
            best = max(best, (long long)height*width);
        }
        st.push(i);
    }
    return best;
}
int main(){
    int m,n;
    vector<int> heights;
    bool first=true;
    while (cin>>m>>n && (m||n)) {
        vector<vector<int>> grid(m, vector<int>(n));
        for (auto &row: grid) for (auto &x: row) cin>>x;
        if (first) { heights.assign(n,0); first=false; }
        long long best=0;
        for (int i=0;i<m;i++){
            for (int j=0;j<n && j<(int)heights.size();j++) heights[j] = grid[i][j]==0 ? heights[j]+1 : 0;
            best = max(best, largestRectHistogram(heights));
        }
        cout << best << "\n";
    }
}
